ALTER  PROCEDURE Wd37schema.sp_get_emp
AS
BEGIN
DECLARE @r_cnt int=0;

PRINT 'Process started...'

PRINT 'step 1 : getting the count'
select @r_cnt=count(1) from  Wd37schema.emp;

PRINT 'step 2 : Total Employess :'+ CAST(@r_cnt as VARCHAR(10));

PRINT ' Step 3 : printing all employee ...';

select * from Wd37schema.emp;

PRINT 'Process completed...'

END
